DROP TABLE IF EXISTS `indicator_captures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `indicator_captures` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `indicator_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `period_id` bigint unsigned NOT NULL,
  `input_data` json NOT NULL,
  `numerator` decimal(14,2) NOT NULL,
  `denominator` decimal(14,2) NOT NULL,
  `result_percentage` decimal(8,2) NOT NULL,
  `complies` tinyint(1) NOT NULL,
  `analysis_text` longtext COLLATE utf8mb4_unicode_ci,
  `created_by_user_id` bigint unsigned DEFAULT NULL,
  `updated_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `indicator_captures_unique` (`indicator_id`,`user_id`,`period_id`),
  KEY `indicator_captures_period_id_foreign` (`period_id`),
  KEY `indicator_captures_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `indicator_captures_updated_by_user_id_foreign` (`updated_by_user_id`),
  KEY `indicator_captures_indicator_id_index` (`indicator_id`),
  KEY `indicator_captures_user_id_foreign` (`user_id`),
  CONSTRAINT `indicator_captures_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `indicator_captures_indicator_id_foreign` FOREIGN KEY (`indicator_id`) REFERENCES `indicators` (`id`) ON DELETE CASCADE,
  CONSTRAINT `indicator_captures_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `indicator_periods` (`id`) ON DELETE CASCADE,
  CONSTRAINT `indicator_captures_updated_by_user_id_foreign` FOREIGN KEY (`updated_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `indicator_captures_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

