--
-- Table structure for table `quality_document_areas`
--

DROP TABLE IF EXISTS `quality_document_areas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_document_areas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `quality_document_id` bigint unsigned NOT NULL,
  `area_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
